import * as THREE from 'three';
import {configureSourceTangentMaterial,injectSourceTangentFrame,sourceTangentProgramKey} from './source-tangent-frame.js';

// Generated by tools/materials/master2uv-prepare.py. Source material math and
// renderer mappings are deliberately recorded separately in the asset document.
export const MASTER2UV_GLSL = __MASTER2UV_GLSL__;
const ROLES = ['baseNormal', 'globalWear', 'wear', 'id', 'normalAO', 'grunge', 'anodized', 'rubber', 'metalCS', 'metalNormal', 'aluminium'];

function fingerprint(array) {
  const bytes = new Uint8Array(array.buffer, array.byteOffset, array.byteLength);
  let hash = 2166136261;
  for (const byte of bytes) hash = Math.imul(hash ^ byte, 16777619) >>> 0;
  return hash;
}

export async function prepareRecoveredMaster2UvMaterials(document, manager) {
  if (!document?.materials?.length) return { apply() {}, applyGeometry() {}, applied: 0, provenance: null };
  const loader = new THREE.TextureLoader(manager), binary = new THREE.FileLoader(manager).setResponseType('arraybuffer'), textures = new Map();
  const sources = new Map(Object.values(document.sourceTextures).map(row => [row.url, row]));
  const urls = [...new Set(document.materials.flatMap(row => Object.values(row.textures)))];
  // Bound decoder work while loading the shared textures once per document.
  let next = 0;
  await Promise.all(Array.from({ length: Math.min(4, urls.length) }, async () => {
    while (next < urls.length) {
      const url = urls[next++], source = sources.get(url);
      if (!source) throw new Error(`Missing Master2UV texture provenance: ${url}`);
      const texture = await loader.loadAsync(url);
      texture.colorSpace = source.colorSpace === 'srgb' ? THREE.SRGBColorSpace : THREE.NoColorSpace;
      texture.flipY = false;
      texture.wrapS = texture.wrapT = THREE.RepeatWrapping;
      texture.minFilter = THREE.LinearMipmapLinearFilter;
      texture.magFilter = THREE.LinearFilter;
      textures.set(url, texture);
    }
  }));
  const uvBytes = await binary.loadAsync(document.uv1.url);
  if (uvBytes.byteLength !== document.uv1.byteLength) throw new Error('Invalid original Master2UV UV1 payload');
  const records = new Map();
  for (const row of document.uv1.records) {
    if (row.byteLength !== row.vertexCount * 8 || row.byteOffset < 0 || row.byteOffset + row.byteLength > uvBytes.byteLength) throw new Error('Invalid Master2UV UV1 record');
    const key = `${row.assetId}/${row.sourceLod}`, list = records.get(key) ?? [];
    list.push(row); records.set(key, list);
  }
  const recipes = new Map(document.materials.map(row => [`${row.assetId}/${row.materialId}`, row]));
  let applied = 0, geometries = 0;
  function applyGeometry(gltf, asset, sourceLod = 0) {
    const rows = records.get(`${asset.id ?? asset.assetId}/${sourceLod}`);
    if (!rows) return;
    const primitives = new Map();
    gltf.scene.traverse(mesh => { if (mesh.isMesh) primitives.set(gltf.parser.associations.get(mesh)?.primitives, mesh); });
    for (const row of rows) {
      const mesh = primitives.get(row.primitiveIndex), geometry = mesh?.geometry;
      if (!geometry || geometry.attributes.position.count !== row.vertexCount || geometry.index?.count !== row.indexCount ||
          fingerprint(geometry.attributes.uv.array) !== row.uv0Fingerprint || fingerprint(geometry.index.array) !== row.indexFingerprint) {
        throw new Error(`Original Master2UV primitive correspondence mismatch: ${row.assetId}/LOD${sourceLod}/${row.primitiveIndex}`);
      }
      if (geometry.userData.recoveredMaster2Uv?.sourceUv1Sha256 === row.uv1Sha256) continue;
      const attribute = new THREE.BufferAttribute(new Float32Array(uvBytes, row.byteOffset, row.vertexCount * 2), 2);
      geometry.setAttribute('bf2Master2Uv1', attribute);
      geometry.userData.recoveredMaster2Uv = { evidenceId: document.uv1.evidenceId, sourceUv1Sha256: row.uv1Sha256, sourceLod, primitiveIndex: row.primitiveIndex };
      geometries++;
    }
  }
  return {
    provenance: { evidenceId: document.evidenceId, sections: recipes.size, textures: textures.size, uvRecords: document.uv1.records.length, runtimeMapping: document.runtimeMapping, limitations: document.limitations },
    get applied() { return applied; },
    get geometries() { return geometries; },
    applyGeometry,
    apply(gltf, asset) {
      applyGeometry(gltf, asset, 0);
      gltf.scene.traverse(mesh => {
        if (!mesh.isMesh) return;
        for (const material of [].concat(mesh.material)) {
          if (material.userData.recoveredMaster2UvShader) continue;
          const recipe = recipes.get(`${asset.id}/${material.userData.sourceMaterialId}`);
          if (!recipe) continue;
          if (!mesh.geometry.getAttribute('uv') || !mesh.geometry.getAttribute('bf2Master2Uv1')) throw new Error(`Source Master2UV mesh has no UV0: ${asset.id}/${recipe.materialId}`);
          material.color.setRGB(1, 1, 1);
          material.roughness = 1;
          material.metalness = 0;
          material.map = material.normalMap = material.roughnessMap = material.metalnessMap = material.aoMap = material.emissiveMap = null;
          material.emissive?.setRGB(0, 0, 0);
          material.userData.recoveredMaster2UvShader = { evidenceId: document.evidenceId, sourceShader: recipe.sourceShader, runtimeMapping: document.runtimeMapping, nativeLightingInputs: document.nativeLightingInputs };
          material.userData.placeholder = false;
          material.userData.neutralColorApproximation = false;
          configureSourceTangentMaterial(material,mesh.geometry);
          material.onBeforeCompile = function(shader) {
            for (const role of ROLES) shader.uniforms[`bf2_master2uv_${role}`] = { value: textures.get(recipe.textures[role]) };
            shader.uniforms.bf2_master2uv_cb = { value: recipe.constants.map(v => new THREE.Vector4(...v)) };
            shader.vertexShader = `attribute vec2 bf2Master2Uv1;
              varying vec4 bf2_master2uv_uv;
              varying vec3 bf2_master2uv_world;
              varying vec3 bf2_master2uv_geometricNormal;
            ` + shader.vertexShader;
            shader.vertexShader = shader.vertexShader.replace('#include <worldpos_vertex>', `#include <worldpos_vertex>
              vec4 bf2_master2uv_wp = vec4(transformed, 1.0);
              #ifdef USE_INSTANCING
                bf2_master2uv_wp = instanceMatrix * bf2_master2uv_wp;
              #endif
              bf2_master2uv_world = (modelMatrix * bf2_master2uv_wp).xyz;
              bf2_master2uv_geometricNormal = inverseTransformDirection(transformedNormal, viewMatrix);
              bf2_master2uv_uv = vec4(uv, bf2Master2Uv1);
            `);
            shader.fragmentShader = `varying vec4 bf2_master2uv_uv;
              varying vec3 bf2_master2uv_world;
              varying vec3 bf2_master2uv_geometricNormal;
              uniform vec4 bf2_master2uv_cb[9];
              ${ROLES.map(role => `uniform sampler2D bf2_master2uv_${role};`).join('\n')}
              ${MASTER2UV_GLSL}
              // Native packed tangents have not been recovered. Reconstruct the
              // UV cotangent frame rather than imposing a guessed fixed axis.
              mat3 bf2_master2uv_tbn(vec3 position, vec3 n, vec2 uvValue) {
                vec3 q0 = dFdx(position), q1 = dFdy(position);
                vec2 st0 = dFdx(uvValue), st1 = dFdy(uvValue);
                vec3 q1perp = cross(q1, n), q0perp = cross(n, q0);
                vec3 tangent = q1perp * st0.x + q0perp * st1.x;
                vec3 bitangent = q1perp * st0.y + q0perp * st1.y;
                float invmax = inversesqrt(max(max(dot(tangent, tangent), dot(bitangent, bitangent)), 1e-16));
                return mat3(tangent * invmax, bitangent * invmax, n);
              }
            ` + shader.fragmentShader;
            shader.fragmentShader = shader.fragmentShader.replace('#include <color_fragment>', `#include <color_fragment>
              Master2UVSurface bf2_master2uv_surface = sampleMaster2UV(bf2_master2uv_uv.xy, bf2_master2uv_uv.zw, bf2_master2uv_world,
                bf2_master2uv_geometricNormal, bf2_master2uv_cb,
                ${ROLES.map(role => `bf2_master2uv_${role}`).join(', ')});
              diffuseColor.rgb = bf2_master2uv_surface.color;
            `);
            shader.fragmentShader = shader.fragmentShader.replace('#include <roughnessmap_fragment>', `#include <roughnessmap_fragment>
              roughnessFactor = 1.0 - clamp(bf2_master2uv_surface.smoothness, 0.0, 1.0);
            `);
            shader.fragmentShader = shader.fragmentShader.replace('#include <metalnessmap_fragment>', `#include <metalnessmap_fragment>
              metalnessFactor = clamp(bf2_master2uv_surface.materialScalar, 0.0, 1.0);
            `);
            shader.fragmentShader = shader.fragmentShader.replace('#include <normal_fragment_maps>', `
              mat3 bf2_master2uv_frame = bf2_master2uv_tbn(-vViewPosition, normal, bf2_master2uv_uv.xy);
              normal = normalize(bf2_master2uv_frame * bf2_master2uv_surface.tangentNormal);
            `);
            shader.fragmentShader = shader.fragmentShader.replace('#include <aomap_fragment>', `#include <aomap_fragment>
              reflectedLight.indirectDiffuse *= bf2_master2uv_surface.ao;
            `);
            injectSourceTangentFrame(shader,this,'master2uv');
          };
          material.customProgramCacheKey = function() { return 'bf2-source-SS_DSI_Master_2UV-2304f89b0d-v3|' + sourceTangentProgramKey(this); };
          material.needsUpdate = true;
          applied++;
        }
      });
    },
  };
}
